-- Regulars initial schema (technical-architecture.md §1, §9).
-- Generated by `uv run python -m regulars.db.gen_ddl`; do not edit by hand.

CREATE TABLE groups (
	id VARCHAR(36) NOT NULL,
	zip VARCHAR(16) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	assembly_method VARCHAR(16) NOT NULL,
	status VARCHAR(32) NOT NULL,
	CONSTRAINT pk_groups PRIMARY KEY (id),
	CONSTRAINT ck_groups_assembly_method CHECK (assembly_method IN ('model', 'random'))
);

CREATE TABLE users (
	id VARCHAR(36) NOT NULL,
	phone_hash VARCHAR(128) NOT NULL,
	zip VARCHAR(16) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	status VARCHAR(32) NOT NULL,
	exploration_flag BOOLEAN NOT NULL,
	CONSTRAINT pk_users PRIMARY KEY (id),
	CONSTRAINT uq_users_phone_hash UNIQUE (phone_hash)
);

CREATE TABLE memberships (
	group_id VARCHAR(36) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	joined_round INTEGER NOT NULL,
	left_round INTEGER,
	exit_reason VARCHAR(64),
	CONSTRAINT pk_memberships PRIMARY KEY (group_id, user_id, joined_round),
	CONSTRAINT ck_memberships_left_after_joined CHECK (left_round IS NULL OR left_round >= joined_round),
	CONSTRAINT fk_memberships_group_id_groups FOREIGN KEY(group_id) REFERENCES groups (id),
	CONSTRAINT fk_memberships_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE TABLE messages (
	id VARCHAR(36) NOT NULL,
	group_id VARCHAR(36) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	sent_at_ms BIGINT NOT NULL,
	body TEXT NOT NULL,
	reply_to VARCHAR(36),
	tapback_target VARCHAR(36),
	char_count INTEGER NOT NULL,
	CONSTRAINT pk_messages PRIMARY KEY (id),
	CONSTRAINT fk_messages_group_id_groups FOREIGN KEY(group_id) REFERENCES groups (id),
	CONSTRAINT fk_messages_user_id_users FOREIGN KEY(user_id) REFERENCES users (id),
	CONSTRAINT fk_messages_reply_to_messages FOREIGN KEY(reply_to) REFERENCES messages (id),
	CONSTRAINT fk_messages_tapback_target_messages FOREIGN KEY(tapback_target) REFERENCES messages (id)
);

CREATE INDEX ix_messages_group_sent ON messages (group_id, sent_at_ms);

CREATE TABLE persona_versions (
	id VARCHAR(36) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	version INTEGER NOT NULL,
	spec_json JSON NOT NULL,
	source VARCHAR(32) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_persona_versions PRIMARY KEY (id),
	CONSTRAINT uq_persona_versions_user_id_version UNIQUE (user_id, version),
	CONSTRAINT ck_persona_versions_source CHECK (source IN ('voice_interview', 'chat_behavior', 'chatlog_import', 'user_correction')),
	CONSTRAINT ck_persona_versions_version_positive CHECK (version >= 1),
	CONSTRAINT fk_persona_versions_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE TABLE plans (
	id VARCHAR(36) NOT NULL,
	group_id VARCHAR(36) NOT NULL,
	proposed_at TIMESTAMP WITH TIME ZONE NOT NULL,
	locked_at TIMESTAMP WITH TIME ZONE,
	venue VARCHAR(255),
	starts_at TIMESTAMP WITH TIME ZONE,
	CONSTRAINT pk_plans PRIMARY KEY (id),
	CONSTRAINT fk_plans_group_id_groups FOREIGN KEY(group_id) REFERENCES groups (id)
);

CREATE INDEX ix_plans_group_id ON plans (group_id);

CREATE TABLE predictions (
	id VARCHAR(36) NOT NULL,
	user_a VARCHAR(36) NOT NULL,
	user_b VARCHAR(36) NOT NULL,
	judge_version VARCHAR(64) NOT NULL,
	y_hat FLOAT NOT NULL,
	y_hat_calibrated FLOAT,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_predictions PRIMARY KEY (id),
	CONSTRAINT fk_predictions_user_a_users FOREIGN KEY(user_a) REFERENCES users (id),
	CONSTRAINT fk_predictions_user_b_users FOREIGN KEY(user_b) REFERENCES users (id)
);

CREATE INDEX ix_predictions_pair ON predictions (user_a, user_b);

CREATE TABLE attendance (
	plan_id VARCHAR(36) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	attended BOOLEAN NOT NULL,
	source VARCHAR(32) NOT NULL,
	CONSTRAINT pk_attendance PRIMARY KEY (plan_id, user_id),
	CONSTRAINT fk_attendance_plan_id_plans FOREIGN KEY(plan_id) REFERENCES plans (id),
	CONSTRAINT fk_attendance_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE TABLE audit_log (
	id VARCHAR(36) NOT NULL,
	actor VARCHAR(64) NOT NULL,
	decision_type VARCHAR(64) NOT NULL,
	subject_user_id VARCHAR(36),
	group_id VARCHAR(36),
	plan_id VARCHAR(36),
	persona_version_id VARCHAR(36),
	judge_version VARCHAR(64),
	reason TEXT NOT NULL,
	payload_json JSON NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_audit_log PRIMARY KEY (id),
	CONSTRAINT fk_audit_log_subject_user_id_users FOREIGN KEY(subject_user_id) REFERENCES users (id),
	CONSTRAINT fk_audit_log_group_id_groups FOREIGN KEY(group_id) REFERENCES groups (id),
	CONSTRAINT fk_audit_log_plan_id_plans FOREIGN KEY(plan_id) REFERENCES plans (id),
	CONSTRAINT fk_audit_log_persona_version_id_persona_versions FOREIGN KEY(persona_version_id) REFERENCES persona_versions (id)
);

CREATE INDEX ix_audit_log_created_at ON audit_log (created_at);

CREATE INDEX ix_audit_log_group_id ON audit_log (group_id);

CREATE INDEX ix_audit_log_subject_user_id ON audit_log (subject_user_id);

CREATE TABLE deposit_credits (
	id VARCHAR(36) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	plan_id VARCHAR(36),
	amount_cents INTEGER NOT NULL,
	kind VARCHAR(32) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_deposit_credits PRIMARY KEY (id),
	CONSTRAINT ck_deposit_credits_kind CHECK (kind IN ('deposit_hold', 'forfeit', 'redistributed_credit', 'applied')),
	CONSTRAINT fk_deposit_credits_user_id_users FOREIGN KEY(user_id) REFERENCES users (id),
	CONSTRAINT fk_deposit_credits_plan_id_plans FOREIGN KEY(plan_id) REFERENCES plans (id)
);

CREATE INDEX ix_deposit_credits_plan_id ON deposit_credits (plan_id);

CREATE INDEX ix_deposit_credits_user_id ON deposit_credits (user_id);

CREATE TABLE ratings (
	plan_id VARCHAR(36) NOT NULL,
	rater_id VARCHAR(36) NOT NULL,
	ratee_id VARCHAR(36) NOT NULL,
	would_see_again BOOLEAN NOT NULL,
	felt_connected_1_7 INTEGER,
	submitted_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_ratings PRIMARY KEY (plan_id, rater_id, ratee_id),
	CONSTRAINT ck_ratings_directed CHECK (rater_id <> ratee_id),
	CONSTRAINT ck_ratings_felt_connected_range CHECK (felt_connected_1_7 IS NULL OR (felt_connected_1_7 BETWEEN 1 AND 7)),
	CONSTRAINT fk_ratings_plan_id_plans FOREIGN KEY(plan_id) REFERENCES plans (id),
	CONSTRAINT fk_ratings_rater_id_users FOREIGN KEY(rater_id) REFERENCES users (id),
	CONSTRAINT fk_ratings_ratee_id_users FOREIGN KEY(ratee_id) REFERENCES users (id)
);

CREATE TABLE rsvps (
	plan_id VARCHAR(36) NOT NULL,
	user_id VARCHAR(36) NOT NULL,
	state VARCHAR(32) NOT NULL,
	deposit_intent_id VARCHAR(255),
	paid_at TIMESTAMP WITH TIME ZONE,
	CONSTRAINT pk_rsvps PRIMARY KEY (plan_id, user_id),
	CONSTRAINT fk_rsvps_plan_id_plans FOREIGN KEY(plan_id) REFERENCES plans (id),
	CONSTRAINT fk_rsvps_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE TABLE sims (
	id VARCHAR(36) NOT NULL,
	user_a VARCHAR(36) NOT NULL,
	user_b VARCHAR(36) NOT NULL,
	persona_ver_a VARCHAR(36) NOT NULL,
	persona_ver_b VARCHAR(36) NOT NULL,
	scenario_id VARCHAR(64) NOT NULL,
	seed INTEGER NOT NULL,
	transcript_json JSON NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE NOT NULL,
	CONSTRAINT pk_sims PRIMARY KEY (id),
	CONSTRAINT fk_sims_user_a_users FOREIGN KEY(user_a) REFERENCES users (id),
	CONSTRAINT fk_sims_user_b_users FOREIGN KEY(user_b) REFERENCES users (id),
	CONSTRAINT fk_sims_persona_ver_a_persona_versions FOREIGN KEY(persona_ver_a) REFERENCES persona_versions (id),
	CONSTRAINT fk_sims_persona_ver_b_persona_versions FOREIGN KEY(persona_ver_b) REFERENCES persona_versions (id)
);

CREATE INDEX ix_sims_pair ON sims (user_a, user_b);

CREATE TABLE sim_features (
	sim_id VARCHAR(36) NOT NULL,
	feature_name VARCHAR(64) NOT NULL,
	value FLOAT NOT NULL,
	CONSTRAINT pk_sim_features PRIMARY KEY (sim_id, feature_name),
	CONSTRAINT fk_sim_features_sim_id_sims FOREIGN KEY(sim_id) REFERENCES sims (id)
);

CREATE OR REPLACE FUNCTION persona_versions_reject_update() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'persona_versions is append-only';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER persona_versions_immutable BEFORE UPDATE ON persona_versions
FOR EACH ROW EXECUTE FUNCTION persona_versions_reject_update();
